generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel ?holdingGain ?rebalancingAmount ?scenarioChange ?cashFlowTotal WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?holdingGain) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:returnsPct ?returnsPct .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancingAmount) WHERE {
      ?rebalance a wm:RebalancingAction ;
                 wm:investorId ?investorId ;
                 wm:amount ?amount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?change)) AS ?scenarioChange) WHERE {
      ?scenario a wm:ScenarioRebalancing ;
                wm:investorId ?investorId ;
                wm:newAllocationPct ?newAlloc ;
                wm:currentAllocationPct ?currAlloc .
      BIND ((xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?change)
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowTotal) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    } GROUP BY ?investorId
  }
  OPTIONAL {
    ?inv a wm:Investor ;
         wm:investorId ?investorId ;
         wm:hasRiskTolerance ?rt .
    ?rt rdfs:label ?riskToleranceLabel .
  }
}
ORDER BY ?riskToleranceLabel

